// isValidXMLNameStartChar reports whether r is a valid first character of an
// XML Name, per the XML 1.0 (Fifth Edition) specification §2.3.
func isValidXMLNameStartChar(r rune) bool {
	return r == ':' || r == '_' ||
		(r >= 'A' && r <= 'Z') ||
		(r >= 'a' && r <= 'z') ||
		(r >= 0xC0 && r <= 0xD6) ||
