		{"space and non-ASCII", "/items/{name}", "a b\xe4\xb8\xad", "/items/a%20b%E4%B8%AD"},
		// Values must not be pre-escaped; "%" is always escaped.
		{"pre-escaped value", "/items/{name}", "a%20b", "/items/a%2520b"},
	}
